CREATE DATABASE IF NOT EXISTS scholarconnect CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE scholarconnect;
CREATE TABLE IF NOT EXISTS students(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admins(id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(150) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS scholarships(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,department VARCHAR(255) NOT NULL,category VARCHAR(50) NOT NULL,course VARCHAR(100) NOT NULL,eligibility TEXT NOT NULL,benefit TEXT NOT NULL,official_url VARCHAR(500) NOT NULL,deadline DATE NULL,documents TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS contact_messages(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL,subject VARCHAR(200) NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS student_favourites(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,scholarship_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY unique_favourite(student_id,scholarship_id),CONSTRAINT fk_fav_student FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,CONSTRAINT fk_fav_scholarship FOREIGN KEY(scholarship_id) REFERENCES scholarships(id) ON DELETE CASCADE);
